def get_bid(day_context, my_status, opponents_status):
    WATER_REQ = 13
    DAILY_SALARY = 70
    MAX_SUPPLY = 25
    MIN_SUPPLY = 15

    supply = float(day_context['supply'])
    day = int(day_context['day'])
    hp = my_status['hp']
    budget = my_status['budget']
    no_water_days = my_status['no_water_days']

    alive_opponents = []
    prev_bids = []
    rich_aggressive = 0
    needy_opponents = 0

    for opp_id, opp in opponents_status.items():
        if opp.get('alive'):
            alive_opponents.append(opp)
            if opp.get('hp', 0) <= 2 or opp.get('no_water_days', 0) >= 1:
                needy_opponents += 1
            prev = opp.get('previous_trace', {})
            if prev and prev.get('bid') is not None:
                bid = float(prev['bid'])
                prev_bids.append(bid)
                if bid >= 120 and opp.get('budget', 0) >= 500:
                    rich_aggressive += 1

    if budget <= 0:
        return 0.0

    if not alive_opponents:
        return float(min(budget, 20.0))

    highest_prev = max(prev_bids) if prev_bids else 0.0
    avg_prev = sum(prev_bids) / len(prev_bids) if prev_bids else 0.0

    tight_supply = supply <= 17
    abundant_supply = supply >= 22
    emergency = hp <= 2 or no_water_days >= 1
    danger = hp <= 4

    base = 18.0

    if abundant_supply:
        base = 12.0
    elif tight_supply:
        base = 32.0
    else:
        base = 22.0

    if rich_aggressive >= 2:
        base -= 6.0
    elif highest_prev > 0:
        if highest_prev >= 130:
            base -= 4.0
        elif highest_prev <= 60:
            base += 8.0

    if needy_opponents >= 2:
        base += 6.0

    if emergency:
        bid = max(base, min(110.0, highest_prev + 3.0 if highest_prev > 0 else 85.0))
    elif danger and tight_supply:
        bid = max(base, min(85.0, avg_prev * 0.75 + 8.0 if avg_prev > 0 else 58.0))
    elif danger:
        bid = max(base, 42.0)
    else:
        bid = base

    if day >= 8 and hp >= 6 and no_water_days == 0:
        bid = min(bid, 18.0)

    reserve = 0.0
    if hp > 4:
        reserve = DAILY_SALARY * 2
    elif hp > 2:
        reserve = DAILY_SALARY

    max_affordable = budget - reserve
    if emergency:
        max_affordable = budget
    elif max_affordable < 0:
        max_affordable = budget * 0.5

    bid = min(bid, max_affordable)
    bid = min(bid, budget)
    bid = max(0.0, bid)

    if budget < 40 and not emergency:
        bid = min(bid, 10.0)

    return float(round(bid, 2))

def get_bid(day_context, my_status, opponents_status):
    WATER_REQ = 13
    DAILY_SALARY = 150

    # Extract today's supply and day
    supply = float(day_context['supply'])
    day = int(day_context['day'])

    my_hp = my_status['hp']
    my_budget = my_status['budget']

    # Collect yesterday's max bid from alive opponents
    max_prev_bid = 0.0
    alive_opponents = [o for o in opponents_status.values() if o['alive']]
    for opp in alive_opponents:
        trace = opp.get('previous_trace', {})
        if trace and 'bid' in trace and trace['bid'] is not None:
            bid = float(trace['bid'])
            if bid > max_prev_bid:
                max_prev_bid = bid

    # Base bid factor: increase when HP is low
    if my_hp <= 3:
        base_factor = 0.9
    elif my_hp <= 7:
        base_factor = 0.7
    else:
        base_factor = 0.5

    # Adjust based on supply shortage
    if supply < WATER_REQ + 2:
        base_factor = min(1.0, base_factor + 0.2)

    # Consider opponents' aggression: if max_prev_bid > 130, increase
    if max_prev_bid > 130:
        base_factor = min(1.0, base_factor + 0.1)

    # Compute bid: ensure at least a small positive number
    raw_bid = max(1.0, DAILY_SALARY * base_factor)
    # If we have budget to match or beat yesterday's max, do so if necessary
    if my_hp <= 5 and max_prev_bid > 0:
        target = max_prev_bid + 1.0
        if target <= my_budget:
            raw_bid = max(raw_bid, target)

    # Cap bid to budget
    bid = min(my_budget, raw_bid)
    return float(bid)
